pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
        // Initialize the contract minimally. Since C is abstract, we need a concrete implementation.
        // But C is directly deployable (has constructor). We'll just deploy and then call initialize.
        // The test will be run against a modified version where the bug is present.
        // For the reference, the test should pass; for the buggy version, it should fail.
        // We need to set up state so that balanceOf can return meaningful values.
        // Since we cannot call initialize on a non-proxy, we'll use a simpler approach:
        // We'll test the logic of balanceOfBatch directly via a helper contract if needed.
        // But the assignment says we can only interact through c.
        // To avoid initialization issues, we'll assume the contract is already initialized.
        // However, the simplest way is to test the balanceOfBatch function directly on a deployed instance.
        // Since C is abstract due to _disableInitializers in constructor, we need to deploy via proxy pattern.
        // For test purposes, we'll modify the approach: we'll use vm.etch to deploy minimal bytecode.
        // But the assignment says to import C and use new C(). Let's assume C is concrete enough.
        // Actually, C has a constructor that calls _disableInitializers, so it can be deployed.
        // But then we can't call initialize because it's an initializer modifier.
        // To make the test work, we'll create a simple setup that doesn't rely on initialization.
        // We'll test a contract that has balanceOfBatch as it is defined in the provided C.
        // The test will just check the property that for equal-length arrays, results match expected.
    }

    function testFuzz_property(address[] memory accounts, uint256[] memory ids) public {
        vm.assume(accounts.length > 0 && ids.length > 0);
        // We'll test that when arrays have different lengths, the call must revert in the correct version.
        // But the bug is that it does NOT revert. So we check the revert behavior.

        // First, we need to set up some balances. Since we can't call mint, we'll use a workaround.
        // Actually, we can't really set up state easily. Let's change approach: use try/catch.

        // The property: if accounts.length != ids.length, then balanceOfBatch SHOULD revert.
        // In the buggy version, it doesn't revert and returns a wrong array.

        if (accounts.length != ids.length) {
            // In the correct version, this should revert.
            // In the buggy version, it should not revert.
            // We can check by calling and seeing if it reverts.
            // But since we don't know which version we're testing, we just check the property.
            // The assertion: for any mismatched arrays, the call should revert.
            try c.balanceOfBatch(accounts, ids) returns (uint256[] memory) {
                // If it doesn't revert, that's a bug.
                assertTrue(false, "balanceOfBatch should revert on mismatched arrays");
            } catch {
                // Expected revert.
                assertTrue(true);
            }
        } else {
            // For equal-length arrays, it should not revert.
            try c.balanceOfBatch(accounts, ids) returns (uint256[] memory result) {
                assertTrue(result.length == accounts.length, "Result length should equal accounts length");
            } catch {
                // If it reverts even for equal arrays, that's a bug.
                assertTrue(false, "balanceOfBatch should not revert on equal-length arrays");
            }
        }
    }
}

